 */
export async function selectBinSize(page: Page, width: number, depth: number) {
  const paletteTrigger = page.getByRole('button', { name: /Size Brush/i });
  await paletteTrigger.click();

  const sizeButton = page
    .getByRole('button', { name: new RegExp(`select paint size: ${width}×${depth}`, 'i') })
    .first();
  await sizeButton.click();

  // Wait for the paint mode indicator to confirm the selection took effect
  await page
    .getByText(new RegExp(`paint.*${width}×${depth}`, 'i'))
    .waitFor({ state: 'visible', timeout: DEFAULT_TIMEOUT });
}

/**
 * Helper to fill the current layer with bins of selected size.
 */
export async function fillLayerWithSize(page: Page, width: number, depth: number) {
  await selectBinSize(page, width, depth);

  // Fill button is in the sidebar
  const sidebar = getSidebar(page);
  const fillButton = sidebar.getByRole('button', {
    name: new RegExp(`fill with ${width}×${depth}`, 'i'),
